INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66672111', 66672111, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Senior Koordinator Tim Ahli Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGS) Tahun Anggaran 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1386000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Pengadaan Konsultan Senior Koordinator Tim Ahli pada Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGs) Tahun Anggaran 2026.', 'Secara umum tujuan kegiatan ini adalah untuk mempersiapkan berbagai dokumen untuk mendorong pelaksanaan pencapaian TPB/SDGs. Secara khusus tujuan kegiatan ini adalah untuk koordinasi seluruh Pilar Pembangunan Sosial, Ekonomi, Lingkungan serta Tata Kelola dan Hukum, Monitoring dan Evaluasi serta Komunikasi Publik Sekretariat SDGs yang meliputi: Koordinasi nasional TPB/SDGs antara pusat dan daerah secara inklusif; Pengembangan data SDGs dalam Satu Data Indonesia dan Data Spatial, Dashboard dan Emonev Pusat dan Daerah; Perumusan Adendum Metadata Indikator SDGs; Pemutakhiran dokumen Rencana Aksi Nasional TPB/SDGs 2025 – 2030 secara Inklusif; Fasilitasi Kementerian/Lembaga dalam proses Penandaan Anggaran TPB/SDGs; Pemutakhiran Peta Jalan SDGs 2017-2030 secara inklusif; Fasilitasi daerah dalam penyusunan Rencana Aksi Daerah Tujuan Pembangunan Berkelanjutan (RAD-TPB/SDGs); Penyusunan pelaporan pemantauan dan evaluasi pelaksanaan Rencana Aksi Nasional (RAN) dan Rencana Aksi Daerah (RAD) TPB/SDGs Pemerintah dan Non-Pemerintah; Penyusunan Laporan Tahunan Pelaksanaan Pencapaian Tujuan Pembangunan Berkelanjutan dengan annex Best Practices Non-States actors dan SOE; Fasilitasi Koordinasi penyusunan materi dan pelaksanaan Komunikasi TPB/SDGs dengan berbagai pihak serta melibatkan duta SDGs Indonesia. Komunikasi dilakukan baik menggunakan media daring, film pendek tentang SDGs Indonesia maupun melakukan tatap muka dengan para pihak; Diseminasi informasi dan publikasi TPB/SDGs dengan berbagai pemangku kepentingan (Pemerintah, DPR, pihak swasta, filantropi, CSOs, media, akademisi, baik di tingkat nasional maupun daerah); Fasilitasi koordinasi Kerjasama Non-State Actors dalam pelaksanaan SDGs (NGO, FBI4SDGs, Akademisi); Fasilitasi dan koordinasi Kerjasama Internasional dalam kerangka SDGs (HLPF, UNESCAP, UNGA, OECD, Bilateral, Multilateral seperti antara lain ADB, Organisasi Internasional eg SDSN, UCLG, GRI); Fasilitasi Koordinasi SDGs Center yang telah terbentuk dan Pengembangan SDGs Centers pada provinsi yang belum memiliki SDGs Centers; Fasilitasi Koordinasi Kegiatan Duta SDGs; Fasilitasi Koordinasi Kegiatan Duta Kampus SDGs; Koordinasi perencanaan dan penyelenggaraan SDGs Festival tahun 2026; Koordinasi perencanaan dan penyelenggaraan SDGs Annual Conference tahun 2026; Koordinasi dan fasilitasi Pemberian SDGs Award tahun 2026; Koordinasi Perumusan Draft Final Konsep Kelembagaan dan Pengembangan SDGs Financing Hub dan Knowledge Hub (kolaborasi dengan SDGs Academy); Koordinasi perencanaan dan pelaksanaan kegiatan dengan mitra pembangunan yang menjadi mitra Sekretariat SDGs. Koordinasi penyusunan Perpres SDGs periode 2024-2030 dan peraturan turunannya. Tugas-tugas lain yang diberikan oleh pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2925326);
