INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66675776', 66675776, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Manajer Monitoring dan Evaluasi Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGS) Tahun Anggaran 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 511680000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan jasa konsultan Manager Monitoring dan Evaluasi dilakukan dengan tujuan untuk membantu pelaksanaan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGs) Tahun 2026 khusus bidang monitoring dan evaluasi.', 'Adapun ruang lingkup pekerjaan untuk konsultan Manager Monitoring dan Evaluasi adalah: Pengembangan dan pengelolaan sistem database dan monitoring, evaluasi dan laporan pelaksanaan TPB/SDGs pemerintah dan nonpemerintah di tingkat pusat dan daerah. Berkoordinasi secara intensif dengan para pemangku kepentingan untuk pelaksanaan pemantauan dan evaluasi serta pengumpulan data TPB/SDGs baik di tingkat pusat maupun daerah untuk menjamin pelaporan dan pemantauan TPB/SDGs secara reguler. Peningkatan kapasitas pemantauan dan evaluasi TPB/SDGs para pemangku kepentingan di tingkat pusat dan daerah. Fasilitasi dalam rangka pelaksanaan monitoring dan evaluasi kegiatan TPB/SDGs di tingkat pusat dan daerah. Pengembangan tampilan data dan informasi hasil pemantauan dan evaluasi baik dalam Satu Data Indonesia, dashboard maupun tampilan lainnya. Analisis dan memberikan umpan balik laporan pemantauan dan evaluasi TPB/SDGs tingkat pusat dan daerah baik pemerintah maupun non-pemerintah. Penyusunan laporan pemantauan/monitoring semesteran pelaksanaan TPB/SDG yang mencakup pusat dan daerah. Penyiapan data evaluasi capaian pelaksanaan TPB/SDGs yang mencakup pusat dan daerah. Reviu dan Analisis laporan pemantauan dan evaluasi pelaksanaan TPB/SDGs di tingkat provinsi (monev terhadap RAD provinsi). Berkoordinasi dengan seluruh Pilar dan tim bidang lainnya dalam Sekretariat TPB/SDGs. Mensupervisi asisten manajer bidang monitoring dan evaluasi dan database serta programmer dalam pelaksanaan tugas pemantauan/evaluasi TPB/SDGs. Menyampaikan informasi dan laporan yang baik dan tepat waktu kepada Koordinator Tim Ahli Sekretariat Nasional SDGs. Membantu tugas-tugas lain dari Koordinator Tim Ahli Sekretariat Nasional SDGs.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2926382);
